<script setup lang="ts">
import { requestErrorMessage } from '~~/shared/utils/requestError'

import { computed, ref, onMounted, onBeforeUnmount, nextTick } from 'vue'
import RateMoneyFields from './RateMoneyFields.vue'
import ModernDateField from './ModernDateField.vue'
import { rateFormFields } from '~~/shared/utils/rateFields'
import { rateDate, regionalAtDate } from '~~/shared/utils/regionalRates'
const props=defineProps<{mode:'create'|'current'|'version'|'history';record?:any;scope?:any;positions:any[];agencies:any[];regions:any[]}>()
const emit=defineEmits<{close:[];saved:[]}>()
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const current=props.record?regionalAtDate(props.record,props.record.Versions,today):null
const initial=props.mode==='version'?(props.record?.Versions?.at(-1)||props.record):current||props.record
const form=ref<any>({AgencyID:String(props.scope?.AgencyID??''),RegionID:String(props.scope?.RegionID??''),EffectiveDate:props.mode==='version'?'':rateDate(initial?.EffectiveDate)||today,Reason:initial?.Reason||'',...Object.fromEntries(rateFormFields.map(({key})=>[key,initial?.[key]??0]))})
const sourceId=ref(''),busy=ref(false),error=ref(''),review=ref(false),dialog=ref<HTMLElement|null>(null)
const title=computed(()=>({create:'Set up region rate',current:'Edit region rate',version:'Update region rate',history:'Region rate history'})[props.mode])
const candidates=computed(()=>props.positions.filter(row=>row.Status==='Active'&&String(row.AgencyID)===String(form.value.AgencyID)&&String(row.RegionID??'')===String(form.value.RegionID??'')&&row.EffectiveDate))
const source=computed(()=>candidates.value.find(row=>String(row.PayrollRateID)===sourceId.value))
const money=(value:any)=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(value)||0)
const formatDate=(value:any)=>{const d=rateDate(value);return d?new Intl.DateTimeFormat('en-PH',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T00:00:00Z')):'No date'}
const scopeLabel=computed(()=>props.record?props.record.AgencyName+' / '+(props.record.RegionName||'All regions'):(props.agencies.find(a=>String(a.AgencyID)===String(form.value.AgencyID))?.AgencyName||'Select an agency')+' / '+(props.regions.find(r=>String(r.RegionID)===String(form.value.RegionID))?.RegionName||'All regions'))
const history=computed(()=>{const record=props.record;if(!record)return [];const currentDate=rateDate(current?.EffectiveDate);return [{...record,original:true},...(record.Versions||[])].reverse().map(row=>({...row,state:rateDate(row.EffectiveDate)>today?'Scheduled':rateDate(row.EffectiveDate)===currentDate?'Current':'Previous'}))})
const minimum=computed(()=>{if(props.mode!=='version')return undefined;const d=new Date(rateDate(initial.EffectiveDate)+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+1);return d.toISOString().slice(0,10)})
function selectSource(){if(!source.value)return;form.value={...form.value,EffectiveDate:rateDate(source.value.EffectiveDate),...Object.fromEntries(rateFormFields.map(({key})=>[key,source.value[key]??0]))}}
function close(){if(!busy.value)emit('close')}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await $fetch('/api/rates/regional',{method:props.mode==='create'?'POST':'PUT',body:{...form.value,id:props.record?.RegionRateID,mode:props.mode,Revision:props.record?.Revision,SourcePayrollRateID:sourceId.value||undefined}});emit('saved')}catch(e:any){error.value=requestErrorMessage(e, 'Unable to save region rate.');review.value=false}finally{busy.value=false}}
let previous:HTMLElement|null=null,overflow=''
function keyboard(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();close()}if(event.key!=='Tab')return;const nodes=dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),summary,[tabindex="0"]');if(!nodes?.length)return;const first=nodes[0]!,last=nodes[nodes.length-1]!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
onMounted(async()=>{previous=document.activeElement as HTMLElement;overflow=document.body.style.overflow;document.body.style.overflow='hidden';document.addEventListener('keydown',keyboard);await nextTick();dialog.value?.focus()})
onBeforeUnmount(()=>{document.body.style.overflow=overflow;document.removeEventListener('keydown',keyboard);previous?.focus()})
</script>
<template>
 <Teleport to="body"><div class="regional-backdrop" @click.self="close"><form ref="dialog" class="regional-modal" role="dialog" aria-modal="true" aria-labelledby="regional-modal-title" tabindex="-1" @submit.prevent="review?save():review=true">
  <header><div><p>REGIONAL PAYROLL RATE</p><h2 id="regional-modal-title">{{review?'Review region rate':title}}</h2><span>{{scopeLabel}}</span></div><button type="button" class="close" aria-label="Close region rate" :disabled="busy" @click="close"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header>
  <div class="regional-body">
   <template v-if="mode==='history'">
    <p class="intro">The original rate and every dated update are kept for their effective work dates.</p>
    <article v-for="entry in history" :key="entry.RegionRateVersionID||'original'" class="history-card"><div class="history-heading"><div><p>{{entry.original?'ORIGINAL RATE':'REGION RATE UPDATE'}}</p><h3>{{formatDate(entry.EffectiveDate)}}</h3></div><span class="state" :class="entry.state.toLowerCase()">{{entry.state}}</span></div><p v-if="entry.Reason" class="intro">{{entry.Reason}}</p><div class="highlights">Regular <strong>{{money(entry.RegularRate)}}</strong> &middot; OT <strong>{{money(entry.OTRate)}}</strong></div><details :open="entry.state==='Current'"><summary>View all rate amounts</summary><dl><div v-for="field in rateFormFields" :key="field.key"><dt>{{field.label}}</dt><dd>{{money(entry[field.key])}}</dd></div></dl></details></article>
   </template>
   <template v-else-if="review">
    <section class="panel"><p class="eyebrow">CONFIRM DETAILS</p><h3>{{scopeLabel}}</h3><p class="intro">Effective {{formatDate(form.EffectiveDate)}}{{source?' / Starting from '+source.PositionName:''}}</p><p class="note">{{mode==='current'?'This corrects the currently applicable regional amounts.':'Earlier work dates keep their previous rate.'}} Position fields using the regional rate will follow this change. Custom position amounts remain in place.</p><p v-if="source" class="intro">The original amounts and {{source.Versions?.length||0}} dated updates will be copied from this position.</p><dl><div v-for="field in rateFormFields" :key="field.key"><dt>{{field.label}}</dt><dd>{{money(form[field.key])}}</dd></div></dl><p v-if="form.Reason" class="intro">{{form.Reason}}</p></section>
   </template>
   <template v-else>
    <section class="panel"><div class="section-heading"><div><p>ASSIGNMENT</p><h3>Agency and region</h3></div></div><div v-if="mode==='create'" class="two-columns"><label>Agency<select v-model="form.AgencyID" required :disabled="!!scope" @change="sourceId=''"><option value="">Choose agency</option><option v-for="agency in agencies" :key="agency.AgencyID" :value="String(agency.AgencyID)">{{agency.AgencyName}}</option></select></label><label>Region<select v-model="form.RegionID" :disabled="!!scope" @change="sourceId=''"><option value="">All regions</option><option v-for="region in regions" :key="region.RegionID" :value="String(region.RegionID)">{{region.RegionName}}</option></select></label></div><strong v-else>{{scopeLabel}}</strong><p class="note">Positions follow the regional amounts on their effective dates. Each position can keep custom amounts for selected fields.</p></section>
    <section class="panel"><div class="section-heading"><div><p>WHEN &amp; WHY</p><h3>{{mode==='create'?'Starting rate and reference':'Effective date and reference'}}</h3></div></div>
     <label v-if="mode==='create'&&candidates.length" class="source-field">Starting rate<select v-model="sourceId" @change="selectSource"><option value="">Enter regional amounts</option><option v-for="position in candidates" :key="position.PayrollRateID" :value="String(position.PayrollRateID)">{{position.PositionName}} &mdash; {{money(position.CurrentRate?.RegularRate??position.RegularRate)}}</option></select><small>Using a position keeps its original rate and all dated updates.</small></label>
     <div class="two-columns"><div v-if="mode==='current'||source" class="date-summary"><span>Effective date</span><strong>{{formatDate(form.EffectiveDate)}}</strong><small v-if="source">Original starting date. Full history will be included.</small><small v-else>Use Dated update to start a new rate on another date.</small></div><ModernDateField v-else v-model="form.EffectiveDate" label="Effective date" :min="minimum" required/><label>Wage order / reference <input v-model="form.Reason" maxlength="500" placeholder="Reference for this regional rate"></label></div>
    </section>
    <section class="panel"><div class="section-heading"><div><p>RATE AMOUNTS</p><h3>{{mode==='version'?'Updated amounts':'Regional amounts'}}</h3></div><small>PHP amounts</small></div><p v-if="source" class="note">Starting amounts from {{source.PositionName}}. Its later dated updates are also copied.</p><fieldset :disabled="!!source"><RateMoneyFields v-model="form"/></fieldset><p v-if="source" class="intro">To enter different starting amounts, choose Enter regional amounts above.</p></section>
   </template>
   <p v-if="error" class="error" role="alert">{{error}}</p>
  </div>
  <footer><button type="button" :disabled="busy" @click="review?review=false:close()">{{mode==='history'?'Close':review?'Back':'Cancel'}}</button><button v-if="mode!=='history'" class="primary" :disabled="busy">{{busy?'Saving...':review?'Save region rate':'Review region rate'}}</button></footer>
 </form></div></Teleport>
</template>
<style scoped>
.regional-backdrop{position:fixed;inset:0;z-index:310;background:rgba(15,23,42,.52);display:grid;place-items:center;padding:16px}.regional-modal{box-sizing:border-box;display:flex;flex-direction:column;min-height:0;width:min(100%,1080px);max-height:92dvh;border:1px solid var(--theme-line,#dbe4f2);border-radius:18px;background:var(--theme-soft,#f7f9fd);color:var(--theme-ink,#183456);font-family:Inter,system-ui,sans-serif;box-shadow:0 24px 70px #0c1e3c38;outline:0}.regional-modal *{box-sizing:border-box}.regional-modal header{display:flex;flex:none;align-items:flex-start;justify-content:space-between;gap:16px;padding:24px 28px 20px;background:var(--theme-surface,#fff);border-bottom:1px solid var(--theme-line,#dfe7f2);border-radius:18px 18px 0 0}.regional-modal header p,.section-heading p,.eyebrow,.history-heading p{margin:0 0 6px;color:var(--theme-accent,#2563eb);font-size:.72rem;letter-spacing:.08em;font-weight:800}.regional-modal h2{margin:0;font-size:1.6rem;line-height:1.3;color:var(--theme-ink,#112a4e)}.regional-modal header span{display:block;margin-top:7px;font-size:.85rem;color:var(--theme-muted,#71839f);line-height:1.5}.close{display:grid;place-items:center;flex:none;width:34px;height:34px;padding:0;border:0;background:none;color:var(--theme-muted,#536c90);border-radius:8px;cursor:pointer}.close:hover{background:var(--theme-soft,#eef3fb)}.close svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2}.regional-body{min-height:0;overflow-y:auto;overscroll-behavior:contain;display:grid;align-content:start;gap:16px;padding:20px 28px}.panel,.history-card{min-width:0;padding:20px 22px;border:1px solid var(--theme-line,#d9e5f4);border-radius:13px;background:var(--theme-surface,#fff)}.section-heading{display:flex;align-items:end;justify-content:space-between;gap:12px;padding-bottom:13px;margin-bottom:16px;border-bottom:1px solid var(--theme-line,#e8edf5)}.section-heading h3,.panel h3,.history-heading h3{font-size:1rem;margin:0;color:var(--theme-ink,#18365c)}.section-heading small,.intro{color:var(--theme-muted,#71839d);font-size:.8rem;line-height:1.6}.intro{margin:0}.two-columns{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:start;gap:15px}.regional-modal label{display:grid;gap:7px;font-size:.82rem;font-weight:650;color:var(--theme-muted,#4a6080)}.regional-modal input,.regional-modal select{width:100%;min-width:0;min-height:44px;padding:9px 12px;border:1px solid var(--theme-line,#cbd8ec);border-radius:8px;background:var(--theme-surface,#fff);color:var(--theme-ink,#183456);font:inherit}.regional-modal input:focus,.regional-modal select:focus{outline:3px solid var(--theme-line,#e4edff);border-color:#749be6}.regional-modal select:disabled{background:var(--theme-soft,#eff4fb);color:var(--theme-muted,#71839f);opacity:1}.source-field{margin-bottom:16px}.source-field small,.date-summary small{font-weight:400;color:var(--theme-muted,#7b8da7);font-size:.72rem;line-height:1.5}.note{margin:16px 0 0;padding:12px 14px;background:var(--theme-soft,#edf4ff);border-radius:9px;font-size:.79rem;line-height:1.6;color:var(--theme-accent,#456b9b)}.panel>.note{margin-bottom:15px}.date-summary{display:grid;gap:8px;font-size:.83rem}.date-summary span{font-weight:650;color:var(--theme-muted,#4a6080)}.date-summary strong{padding:12px;border:1px solid var(--theme-line,#e0e7f2);border-radius:8px;background:var(--theme-soft,#f7f9fc)}.regional-modal footer{flex:none;display:flex;justify-content:flex-end;gap:10px;padding:16px 28px;border-top:1px solid var(--theme-line,#dfe7f2);border-radius:0 0 18px 18px;background:var(--theme-surface,#fff)}.regional-modal footer button{min-height:42px;padding:10px 16px;border:1px solid var(--theme-line,#cdd9ed);background:var(--theme-surface,#fff);color:var(--theme-accent,#2c5284);border-radius:9px;font:inherit;font-size:.82rem;font-weight:750;cursor:pointer}.regional-modal footer .primary{border-color:#2563eb;background:#2563eb;color:#fff}.regional-modal button:disabled{opacity:.55;cursor:default}.history-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:12px}.state{padding:5px 10px;border-radius:30px;background:var(--theme-soft,#f0f3f8);color:var(--theme-muted,#71839d);font-size:.73rem;font-weight:750}.state.current{background:#e2f6ea;color:#208251}.state.scheduled{background:var(--theme-soft,#eaf1ff);color:var(--theme-accent,#2c62b7)}.highlights{margin:12px 0;font-size:.83rem;color:var(--theme-muted,#71839d)}.highlights strong{color:var(--theme-ink,#183456)}.regional-modal details{margin-top:15px;padding-top:12px;border-top:1px solid var(--theme-line,#edf1f7)}.regional-modal summary{cursor:pointer;font-size:.79rem;color:var(--theme-accent,#2c60ad);font-weight:700}.regional-modal dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 22px;margin:14px 0 0}.regional-modal dl>div{display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px solid var(--theme-line,#edf1f7);font-size:.77rem}.regional-modal dt{color:var(--theme-muted,#71839d)}.regional-modal dd{margin:0;font-weight:700;font-variant-numeric:tabular-nums}.error{padding:12px;background:#fff1f2;border-radius:8px;color:#b42318;font-size:.8rem}fieldset{min-width:0;border:0;padding:0;margin:0}fieldset:disabled{opacity:.7}.regional-modal :deep(.rate-money-grid input){min-height:44px;font-size:.88rem}.regional-modal :deep(.rate-money-grid){gap:14px}@media(max-width:600px){.regional-backdrop{padding:10px}.regional-modal{max-height:calc(100dvh - 20px)}.regional-modal header{padding:18px}.regional-modal h2{font-size:1.3rem}.regional-body{padding:14px;gap:12px}.panel,.history-card{padding:16px}.two-columns,.regional-modal dl{grid-template-columns:1fr}.regional-modal footer{padding:12px 16px}.regional-modal footer button{flex:1}}
</style>
